  flights,
  flightTimes,
  flightNotes,
  flightStatusHistory,
  weatherData,
  historicalWeather,
  airportDaylight,
  scraperLogs,
  aircraftPositions,
  airports,
  pushSubscriptions,
  notificationWatermark,
} from '@airways/database/schema';

